const DBS = ["YOUR_NOTION_DB_MAIN", "YOUR_NOTION_DB_CLOUD", "YOUR_NOTION_DB_SECURITY"];
const TOKEN = "YOUR_NOTION_TOKEN";
const body = {"filter": {"property": "Status", "select": {"equals": "New"}}, "sorts": [{"property": "Score", "direction": "descending"}], "page_size": 20};
let all = [];
for (const db of DBS) {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.notion.com/v1/databases/${db}/query`,
    headers: { 'Authorization': `Bearer ${TOKEN}`, 'Notion-Version': '2022-06-28', 'Content-Type': 'application/json' },
    body, json: true
  });
  if (resp && Array.isArray(resp.results)) all = all.concat(resp.results);
}
all.sort((a,b) => ((b.properties && b.properties.Score && b.properties.Score.number) || 0) - ((a.properties && a.properties.Score && a.properties.Score.number) || 0));
return [{ json: { results: all } }];

const resp = $input.first().json;
const results = resp.results || [];

if (results.length === 0) {
  return [{ json: {
    content: '✅ **Job Scout — All caught up!** No unreviewed jobs in Notion. Check back after tomorrow morning\'s run.',
    username: 'Job Scout'
  }}];
}

const notionUrl = 'https://www.notion.so/YOUR_NOTION_DB_URL';
const top = results.slice(0, 5);

let msg = `📬 **Job Scout — Evening Check-In**\n`;
msg += `You have **${results.length} unreviewed job${results.length !== 1 ? 's' : ''}** waiting in Notion.\n\n`;

for (const p of top) {
  const props = p.properties || {};
  const title = props['Job Title']?.title?.[0]?.text?.content || 'Unknown';
  const company = props['Company']?.rich_text?.[0]?.text?.content || '';
  const score = props['Score']?.number ?? '?';
  const priority = props['Priority']?.select?.name || '';
  const applyUrl = props['Apply URL']?.url || '';
  const pageUrl = p.url || '';

  const priBadge = priority === 'High' ? '🔥' : priority === 'Medium' ? '⭐' : '•';
  msg += `${priBadge} **${score}** — **${title}** @ ${company}\n`;
  if (applyUrl) msg += `   Apply: ${applyUrl}\n`;
}

msg += `\n[📋 Open all in Notion](${notionUrl})`;
msg += `\n\n*Update Status to "Applied" in Notion when you apply — you got this!*`;

return [{ json: { content: msg, username: 'Job Scout' } }];
